"""Use a FacetsMeta pre-generated by CADENCE instead of scanning the repository.

CADENCE's cohort step (BUILD_FACETS_META_2N) pickles a FacetsMeta beside the 2n research/autoqc cohort:

    <repo>/../cohort_level/<yyyy_MM_dd>/research/autoqc/<prefix>.facets_meta.<mode>.pkl

built with fit_class="research", FitPolicy.cadence_autoqc() and keep_all_normals=True, and reconciled
against that cohort before it is published. A job asking for exactly those settings can load the most
recent pickle instead of re-reading ~100k manifests. ``load_prebuilt_meta`` returns (meta, info): meta is
None when no suitable pickle exists, and info says why, so the caller builds the meta itself instead.

To make a prebuilt meta interchangeable with a live build of the same request, it is post-processed the
way parseClinicalSample() would have shaped it:
  * clinical maps are re-read from the REQUEST's clinical file (the pickle carries the pipeline run's);
    with a clinical file, only pairs whose tumor is in it are kept, as a live build only visits those;
  * a sample list keeps only the listed tumors / pairs, and unmatched_sample_ids is recomputed.
What it cannot do is see fits reviewed after the pickle was built: info["stamp"] says how old it is.

Safety: pickles are only ever read from the repository's own cohort_level tree (never a caller-chosen
path), are opened read-only, and are never written. Unpickling runs code, so the trust boundary is the
repository: whoever can write cohort_level can already change every FACETS result.
"""
import glob
import os
import pickle
import re

import pandas as pd

from .fitpolicy import FitPolicy

COHORT_POLICY = "autoqc"
COHORT_CLASS = "research"
_STAMP_RE = re.compile(r"^\d{4}_\d{2}_\d{2}$")


def cohort_level_dir(facets_dir):
    """<repo>/all -> <repo>/cohort_level."""
    return os.path.join(os.path.dirname(os.path.normpath(facets_dir)), "cohort_level")


def find_prebuilt_meta(facets_dir, mode):
    """Newest-first list of (stamp, pickle path) for ``mode`` under the repository's cohort_level tree."""
    root = cohort_level_dir(facets_dir)
    found = []
    if not os.path.isdir(root):
        return found
    for stamp in sorted(os.listdir(root), reverse=True):
        if not _STAMP_RE.match(stamp):
            continue
        pattern = os.path.join(root, stamp, COHORT_CLASS, COHORT_POLICY, "*.facets_meta.%s.pkl" % mode)
        for path in sorted(glob.glob(pattern)):
            found.append((stamp, path))
    return found


def _same_dir(a, b):
    return os.path.normpath(str(a)) == os.path.normpath(str(b))


def _mismatch(meta, facets_dir, mode, fit_class):
    """Why a loaded pickle cannot stand in for this request, or None."""
    checks = (
        ("facets_repo_path", getattr(meta, "facets_repo_path", None), facets_dir, _same_dir),
        ("hisens_vs_purity", getattr(meta, "hisens_vs_purity", None), mode, None),
        ("fit_class", getattr(meta, "fit_class", None), fit_class, None),
        ("fit_policy", getattr(meta, "fit_policy", None), FitPolicy.cadence_autoqc(), None),
        ("keep_all_normals", getattr(meta, "keep_all_normals", None), True, None),
        ("selectSingleRun", getattr(meta, "selectSingleRun", None), True, None),
    )
    for name, got, want, same in checks:
        if not (same(got, want) if same else got == want):
            return "%s is %r, request needs %r" % (name, got, want)
    if not getattr(meta, "master_file_dict", None):
        return "pickle holds no runs"
    return None


def _apply_clinical(meta, clinical_file):
    """Replace the clinical maps from ``clinical_file`` and drop runs whose tumor it lacks."""
    df = pd.read_csv(clinical_file, sep="\t", low_memory=False)
    missing = [c for c in meta.CLINICAL_REQUIRED_COLUMNS if c not in df.columns]
    if missing:
        raise ValueError("clinical file %s lacks column(s): %s" % (clinical_file, ", ".join(missing)))
    columns = {"PATIENT_ID": "patient_id_map", "CANCER_TYPE": "cancer_type_map",
               "CANCER_TYPE_DETAILED": "cancer_type_detail_map", "TUMOR_PURITY": "clinical_purity_map",
               "ONCOTREE_CODE": "onkotree_code_map", "CVR_TMB_SCORE": "cvr_tmb_score_map", "MSI_SCORE": "msi_score_map"}
    ids = df["SAMPLE_ID"].astype(str).tolist()
    for column, attr in columns.items():
        setattr(meta, attr, dict(zip(ids, df[column].tolist())))
    meta.clinical_sample_file = clinical_file
    meta.hasClinicalMeta = True
    known = set(ids)
    _keep(meta, lambda key: meta.shortId(key) in known)
    return known


def _keep(meta, wanted):
    for key in [k for k in meta.master_file_dict if not wanted(k)]:
        del meta.master_file_dict[key]
        meta.fit_map.pop(key, None)
        meta.long_id_map.pop(key, None)


def _read_ids(sample_file):
    with open(sample_file, encoding="utf-8-sig") as fh:
        return [line.strip() for line in fh if line.strip() and not line.strip().startswith("#")]


def load_prebuilt_meta(facets_dir, mode, fit_class, clinical_file="", sample_file=None):
    """Return (meta, info). meta is None when no pickle fits the request; info["reason"] says why.

    info always has "requested": True and "used"; when used, also "path", "stamp", "built_at",
    "pairs_in_pickle" and "pairs_after_selection".
    """
    info = {"requested": True, "used": False}
    if fit_class != COHORT_CLASS:
        info["reason"] = "pre-generated metas exist only for fit_class=%s" % COHORT_CLASS
        return None, info
    candidates = find_prebuilt_meta(facets_dir, mode)
    if not candidates:
        info["reason"] = "no %s pickle under %s" % (mode, cohort_level_dir(facets_dir))
        return None, info

    rejected = []
    for stamp, path in candidates:
        try:
            with open(path, "rb") as fh:
                meta = pickle.load(fh)
        except Exception as e:  # unreadable / truncated / older incompatible class: try the next stamp
            rejected.append("%s: unreadable (%s)" % (stamp, e.__class__.__name__))
            continue
        why = _mismatch(meta, facets_dir, mode, fit_class)
        if why:
            rejected.append("%s: %s" % (stamp, why))
            continue

        pairs_in_pickle = len(meta.master_file_dict)
        meta.persist_data = "no"          # never let a later buildFacetsMeta() write anywhere
        meta.run_verbose = False
        known = None
        if clinical_file:
            known = _apply_clinical(meta, clinical_file)
        meta.unmatched_sample_ids = []
        meta.samples_from_file = []
        meta.build_from_file_listing = False
        if sample_file:
            ids = _read_ids(sample_file)
            wanted = {i[0:17] for i in ids}
            _keep(meta, lambda key: meta.shortId(key) in wanted)
            meta.samples_from_file = ids
            meta.build_from_file_listing = True
            # live build: list ids absent from the clinical file (or, without one, from the repository)
            universe = known if known is not None else {meta.shortId(k) for k in meta.master_file_dict}
            meta.unmatched_sample_ids = sorted(wanted - universe)
        info.update(used=True, path=path, stamp=stamp,
                    built_at=getattr(meta, "cadence_built_at", None),
                    pairs_in_pickle=pairs_in_pickle, pairs_after_selection=len(meta.master_file_dict))
        if rejected:
            info["skipped_newer"] = rejected
        return meta, info

    info["reason"] = "no usable pickle: " + "; ".join(rejected)
    return None, info


__all__ = ["load_prebuilt_meta", "find_prebuilt_meta", "cohort_level_dir"]
